async function renderActivity(){panelHead('Activity',[icon('expand','Expand all',()=>document.querySelectorAll('#panel .event').forEach(x=>x.open=true)),icon('collapse','Collapse all',()=>document.querySelectorAll('#panel .event').forEach(x=>x.open=false))]);let rows=events;if(!rows.length){const runs=await records('run',workspace);if(runs[0])rows=(await api('/api/runs/'+runs[0].id)).events}for(const event of rows){const data=event.body,d=el('details',undefined,'event'+(data.status==='failed'||event.type.includes('failed')?' failed':'')),s=el('summary');s.append(el('span',event.type+(data.tool?' · '+data.tool:'')),el('small',new Date(event.created*1000).toLocaleString()));const b=el('div',undefined,'detailbody');debug(b,'Event',data);d.append(s,b);$('panel').append(d)}if(!rows.length)$('panel').append(el('p','No recorded activity.','empty'))}
async function renderCheckpoints(){panelHead('Checkpoints',[icon('reset','Refresh',renderPanel),icon('collapse','Collapse all',()=>document.querySelectorAll('#panel .checkpoint').forEach(x=>x.open=false))]);const rows=await api('/api/checkpoints/'+workspace);for(const x of rows){const d=el('details',undefined,'checkpoint'),s=el('summary');s.append(el('span',x.path),el('small',new Date(x.created*1000).toLocaleString()+' · '+x.reason));d.append(s);let loaded=false;d.ontoggle=attempt(async()=>{if(!d.open||loaded)return;loaded=true;const value=await api('/api/checkpoints/'+workspace+'/'+x.id),b=el('div',undefined,'detailbody');b.append(el('pre',value.diff||'No text differences'));const bar=el('div',undefined,'toolbar');for(const side of ['before','after'])bar.append(btn('Restore '+side,async()=>{if(!confirm('Restore '+side+' version of '+x.path+'? A safety checkpoint will be created.'))return;await api('/api/checkpoints/'+workspace+'/'+x.id+'/restore',{side,expected:value.current});toast('Restored with safety checkpoint.');await renderPanel()}));b.append(bar);d.append(b)});$('panel').append(d)}if(!rows.length)$('panel').append(el('p','No file changes yet.','empty'))}
async function addArtifact(kind){pickImages(async images=>{for(const image of images)await put('artifact',{name:image.name,kind,mime:image.type,data:image.data,time:Date.now()/1000,source:{actor:'user'}},workspace);await renderPanel()})}async function compareImages(){const rows=(await records('artifact',workspace)).filter(x=>x.data?.startsWith('data:image/'));if(rows.length<2)return toast('Add a reference and screenshot first.');modal('Reference / screenshot',p=>{const a=select('Reference','compareA',rows.map(x=>[x.id,x.name]),rows[0].id),b=select('Screenshot','compareB',rows.map(x=>[x.id,x.name]),rows[1].id),grid=el('div',undefined,'comparegrid');function draw(){grid.replaceChildren();for(const id of [a.value,b.value]){const x=rows.find(x=>x.id===id),box=el('div'),im=el('img');im.src=x.data;im.alt=x.name;box.append(el('p',x.name,'note'),im);grid.append(box)}}a.onchange=b.onchange=draw;p.append(grid,el('p','Visual inspection only; no pixel-diff score is invented.','note'));draw()},()=>{},true);$('modalSave').hidden=true}
async function renderArtifacts(){panelHead('Artifacts',[icon('image','Add reference',()=>addArtifact('reference')),icon('scan','Add screenshot',()=>addArtifact('screenshot')),icon('panel','Compare images',compareImages)]);const rows=await records('artifact',workspace);for(const x of rows){const c=card(x.name);c.append(el('div',x.kind+' · '+new Date(x.time*1000).toLocaleString(),'note'));if(x.data?.startsWith('data:image/')){const im=el('img',undefined,'artthumb');im.src=x.data;im.alt=x.name;c.append(im)}if(x.text)c.append(el('pre',x.text));const bar=el('div',undefined,'toolbar');bar.append(icon('scan','Provenance',()=>inspect('Artifact',{id:x.id,source:x.source,consumedBy:x.consumedBy||[]})),icon('download','Export artifact',()=>download(x.name.replace(/[^a-z0-9_-]/gi,'-')+'.json',x)),icon('trash','Delete artifact',async()=>{if(confirm('Delete artifact record?')){await del('artifact',x.id);await renderPanel()}}));c.append(bar);$('panel').append(c)}if(!rows.length)$('panel').append(el('p','No artifacts yet.','empty'))}
async function renderPortability(){$('center').append(head('Import / export','Explicit migration and server-backed export'));const root=content(),m=card('Migrate the approved frontend state','Preview first, then confirm an append-only import with a SQLite backup. Imported agents have browser/file permissions disabled.');m.append(btn('Import frontend state JSON',importState),btn('Find prototype state in this browser',async()=>{const keys=Object.keys(localStorage).filter(k=>k.startsWith('agent-layout-')||k.startsWith('local-agent-unified'));if(!keys.length)return toast('No prototype state on this origin. Export it from the old HTML and import JSON.');const key=keys.sort((a,b)=>Number(b.match(/\d+/)?.[0]||0)-Number(a.match(/\d+/)?.[0]||0))[0];await previewMigration(JSON.parse(localStorage.getItem(key)))}));root.append(m);const exp=card('Export workspace','Includes private prompts, code, conversations, and images. Vault values are not exported.');exp.append(btn('Export workspace JSON',async()=>{const files=await api('/api/files/'+workspace),content={};for(const file of files)if(!file.directory)try{content[file.path]=(await api('/api/file/'+workspace+'?path='+encodeURIComponent(file.path))).content}catch{}const conversations=await records('conversation',workspace),messages=await records('message',workspace);for(const c of conversations)c.messages=messages.filter(m=>m.conversation===c.id);const data={...currentWorkspace(),files:content,conversations,workflows:await records('workflow',workspace),schedules:await records('schedule',workspace),artifacts:await records('artifact',workspace)};download(currentWorkspace().name.replace(/[^a-z0-9_-]/gi,'-')+'.json',{schema:'local-agent.workspace',version:1,workspace:data,agents:state.agents,prompts:state.prompts,memories:await records('memory')})}));root.append(exp,card('Migration limits','Existing server data is appended, not overwritten. Schedules, approvals, external connections, and credentials are not activated by migration. Imported memory needs review.'))}
function importState(){const i=el('input');i.type='file';i.accept='.json,application/json';i.onchange=attempt(async()=>{if(i.files[0].size>12000000)return toast('JSON exceeds 12 MB.');await previewMigration(JSON.parse(await i.files[0].text()))});i.click()}async function previewMigration(value){const data=value.workspaces?value:value.workspace?{workspaces:[value.workspace],agents:value.agents||[],prompts:value.prompts||[],memories:value.memories||[]}:null;if(!data)return toast('Expected prototype state or exported workspace JSON.');const preview=await api('/api/migrate',{state:data,confirm:false});modal('Review migration',p=>{debug(p,'Preview · nothing written',preview);p.append(el('p','Confirmation creates new workspaces and a database backup.','note'))},async()=>{const result=await api('/api/migrate',{state:data,confirm:true});await refresh();await renderCenter();setTimeout(()=>inspect('Migration report',result),0)},true);$('modalSave').textContent='Confirm migration'}
async function renderCenter(){$('center').replaceChildren();const renderers={chat:renderChat,workflow:renderWorkflow,scheduler:renderScheduler,memory:renderMemory,resources:renderResources,health:renderHealth,tools:renderTools,prompts:renderPrompts,diagnostics:renderDiagnostics,credentials:renderCredentials,portability:renderPortability};await (renderers[view]||renderChat)()}
function widths(){const left=Math.max(180,Math.min(380,Number(localStorage.getItem('app.left')||234))),right=Math.max(300,Math.min(760,Number(localStorage.getItem('app.right')||400)));document.documentElement.style.setProperty('--left',left+'px');document.documentElement.style.setProperty('--right',right+'px');for(const [id,value,min,max] of [['leftSplit',left,180,380],['rightSplit',right,300,760]]){const e=$(id);e.setAttribute('aria-valuenow',value);e.setAttribute('aria-valuemin',min);e.setAttribute('aria-valuemax',max)}}for(const [id,key,dir,reset,min,max] of [['leftSplit','left',1,234,180,380],['rightSplit','right',-1,400,300,760]]){const e=$(id);let drag=null;e.onpointerdown=p=>{if(p.button!==0)return;drag={x:p.clientX,width:Number(localStorage.getItem('app.'+key)||reset)};e.setPointerCapture(p.pointerId);document.body.classList.add('dragging')};e.onpointermove=p=>{if(!drag)return;localStorage.setItem('app.'+key,Math.max(min,Math.min(max,drag.width+(p.clientX-drag.x)*dir)));widths();drawEdges()};e.onpointerup=e.onpointercancel=e.onlostpointercapture=()=>{drag=null;document.body.classList.remove('dragging')};e.ondblclick=()=>{localStorage.setItem('app.'+key,reset);widths()};e.onkeydown=p=>{if(!['ArrowLeft','ArrowRight','Home'].includes(p.key))return;p.preventDefault();const value=p.key==='Home'?reset:Number(localStorage.getItem('app.'+key)||reset)+(p.key==='ArrowRight'?10:-10)*dir;localStorage.setItem('app.'+key,Math.max(min,Math.min(max,value)));widths()}}addEventListener('resize',()=>{widths();requestAnimationFrame(drawEdges)});document.addEventListener('pointerdown',e=>{if(!$('contextMenu').contains(e.target))$('contextMenu').hidden=true});document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('contextMenu').hidden=true;connectFrom=null}});$('logo').append(glyph('layers'));attempt(async()=>{widths();await refresh();await renderCenter();await renderPanel();if(innerWidth<950)document.body.classList.add('hide-right');if(activeRun)startPoll(activeRun)})();
